function go(id){document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));document.getElementById(id).classList.add('active');document.querySelectorAll('.nav a').forEach(x=>x.classList.toggle('active',x.dataset.view===id));let names={dashboard:'Dashboard',path:'Learning Path',mission:'Daily Mission',lesson:'Learning Library',sql:'SQL Lab',quiz:'Assessments',projects:'Projects',cases:'Case Studies',interview:'Interview Center',portfolio:'Portfolio',metrics:'Metrics Dictionary'};document.getElementById('crumb').textContent=names[id];document.getElementById('crumbTail').textContent=id==='dashboard'?' / Overview':'';window.scrollTo(0,0)}
