function answer(btn,correct){document.querySelectorAll('#answers button').forEach(b=>b.disabled=true);let f=document.getElementById('feedback');f.style.display='block';f.style.background=correct?'#e8f8ef':'#fff0f1';f.style.color=correct?'#156941':'#a82f38';btn.style.borderColor=correct?'#18a66a':'#e64b55';f.innerHTML=correct?'<b>Correct — analyst thinking starts with a metric tree.</b><br>Revenue can change because traffic, conversion, or average order value changed. Decomposing the outcome tells you where to investigate before proposing a solution.':'<b>Not quite.</b><br>Start with the measurable drivers of revenue: traffic, conversion rate, and average order value. This makes the problem testable.';document.getElementById('nextQuiz').style.display='inline-block'}
