window.toggleUnixStep=function(id){let d=get();if(!d.includes(id))d.push(id);else d=d.filter(x=>x!==id);save(d);showUnixPath(localStorage.getItem('unixSelectedOS')||'mac');toast('Setup checklist updated locally.')};window.copyUnixCommand=function(os,n){let x=(os==='mac'?mac:linux).find(a=>a[0]===n);navigator.clipboard?.writeText(x?.[3]||'').then(()=>toast('Command copied. Review it before running.')).catch(()=>toast('Select and copy the command manually.'))};
